# ---------- Sidebar ----------
with st.sidebar:
    st.markdown("### \U0001f6e1\ufe0f SafeNest PK")
    st.caption("Roman-Urdu / Urdu / English support")

    st.markdown("**Yeh madad kar sakta hai:**")
    categories = [
        ("\U0001f4f5", "Online Harassment"),
        ("\U0001f4b8", "Scams"),
        ("\U0001f512", "Blackmail / Sextortion"),
        ("\U0001f464", "Fake Accounts"),
        ("\U0001f3ad", "Deepfakes"),
    ]
    for icon, label in categories:
        st.markdown(f"<div class='quick-card'>{icon} &nbsp; {label}</div>", unsafe_allow_html=True)

    st.divider()
    st.markdown("**Emergency / Official contacts**")
    st.markdown("- [FIA Cybercrime Wing](https://cybercrime.gov.pk) - helpline **1991**")
    st.markdown("- Digital Rights Foundation helpline - **0800-39393**")
    st.markdown("- Police emergency - **15**")

    st.divider()
    st.caption(
        "\U0001f512 Yeh app chat apne paas save nahi karta. Jawab banane ke liye aap ka message "
        "AI service ko bheja jata hai, is liye personal detail na likhein."
    )

    if st.button("\U0001f5d1\ufe0f Naya conversation shuru karein"):
        st.session_state.messages = []
        st.rerun()

# ---------- Header ----------
st.markdown("<div class='hero-title'>\U0001f6e1\ufe0f SafeNest PK</div>", unsafe_allow_html=True)
st.caption("Privacy-first online safety support - koi bhi personal detail (naam, number, tasveer) na likhein.")

if "messages" not in st.session_state:
    st.session_state.messages = []


def render_reply(reply):
    """Ek bot reply ko screen par dikhata hai (history aur naye jawab dono ke liye)."""
    message = (reply.get("message") or "").strip()
    reason = reply.get("refusal_reason")
    disclaimer = reply.get("disclaimer", "")

    if reply.get("is_refusal"):
        if reason == "self_harm_or_emergency":
            if message:
                st.error(message)
            st.markdown(EMERGENCY_TEXT)
            st.caption(f"Numbers last verified: {EMERGENCY_LAST_VERIFIED}")
        elif reason == "needs_clarification":
            st.info(message or "Kya aap bata sakte hain ke kya hua hai?")
        else:
            st.warning(message or disclaimer or "Yeh sawal is chatbot ke scope se bahar hai.")
        return

    if message:
        st.markdown(message)
    steps = reply.get("checklist", [])
    if steps:
        st.markdown("**Checklist:**")
        for step in steps:
            st.markdown(f"- {step}")
    st.caption(disclaimer)


# ---------- Quick-start examples (only before first message) ----------
if not st.session_state.messages:
    st.markdown("**Jaldi shuru karo:**")
    examples = [
        "Koi ajnabi mujhe harass kar raha hai",
        "Mujhe lottery scam message mila hai",
        "Koi mujhe blackmail kar raha hai",
    ]
    cols = st.columns(len(examples))
    for col, ex in zip(cols, examples):
        if col.button(ex):
            st.session_state.pending_input = ex

# ---------- Render history ----------
for msg in st.session_state.messages:
    with st.chat_message(msg["role"]):
        if msg["role"] == "assistant":
            render_reply(msg["content"])
        else:
            st.markdown(msg["content"])

# ---------- Get input (typed or quick-start button) ----------
user_input = st.chat_input("Apni problem batayein (Roman-Urdu, Urdu ya English mein)...")
if not user_input and "pending_input" in st.session_state:
    user_input = st.session_state.pop("pending_input")

if user_input:
    st.session_state.messages.append({"role": "user", "content": user_input})
    with st.chat_message("user"):
        st.markdown(user_input)

    with st.spinner("Sochte hain... \U0001f6e1\ufe0f"):
        response = client.chat.completions.create(
            model="openai/gpt-oss-20b",
            messages=[
                {"role": "system", "content": combined_system},
                {"role": "user", "content": user_input},
            ],
            response_format={"type": "json_schema", "json_schema": response_schema},
        )
        reply = json.loads(response.choices[0].message.content)

    st.session_state.messages.append({"role": "assistant", "content": reply})

    with st.chat_message("assistant"):
        render_reply(reply)
